parameters.jsCode:
const geminiResponse = $input.first().json;
let updatedPrefs = {};

const candidates = geminiResponse.candidates;
if (candidates && candidates.length > 0) {
  const parts = candidates[0].content.parts;
  if (parts && parts.length > 0) {
    const text = parts[0].text.trim();
    try {
      updatedPrefs = JSON.parse(text);
    } catch (e) {
      console.error('Failed to parse Gemini response:', text);
      return [{ json: { error: 'Failed to parse Gemini response' } }];
    }
  }
}

const currentPrefs = $(''Parse Preferences'').first().json;
const mergedPrefs = {
  ...currentPrefs,
  ...updatedPrefs
};

return [{ json: mergedPrefs }];

const prefs = $input.first().json;
const changes = [];

const current = $(''Parse Preferences'').first().json;

if (prefs.core_interests && JSON.stringify(prefs.core_interests) !== JSON.stringify(current.core_interests)) {
  const added = prefs.core_interests.filter(i => !current.core_interests.includes(i));
  const removed = current.core_interests.filter(i => !prefs.core_interests.includes(i));
  if (added.length) changes.push(`Added ${added.map(a => `"${a}"`).join(', ')} to core interests`);
  if (removed.length) changes.push(`Removed ${removed.map(r => `"${r}"`).join(', ')} from core interests`);
}

if (prefs.excluded_keywords && JSON.stringify(prefs.excluded_keywords) !== JSON.stringify(current.excluded_keywords)) {
  const added = prefs.excluded_keywords.filter(k => !current.excluded_keywords.includes(k));
  const removed = current.excluded_keywords.filter(k => !prefs.excluded_keywords.includes(k));
  if (added.length) changes.push(`Added ${added.map(a => `"${a}"`).join(', ')} to exclusions`);
  if (removed.length) changes.push(`Removed ${removed.map(r => `"${r}"`).join(', ')} from exclusions`);
}

if (prefs.contextual_notes && prefs.contextual_notes !== current.contextual_notes) {
  changes.push(`Updated contextual notes`);
}

const summary = changes.length > 0 ? changes.join('. ') + '.' : 'No changes detected.';

return [{ json: { summary } }];
